<?php
declare(strict_types=1);
namespace App\Controller;
use App\Core\Controller;use App\Core\Response;use App\Repository\ProdottoRepository;use App\Repository\InterventoRepository;
final class MagazzinoController extends Controller
{
 private function repo(): ProdottoRepository{return new ProdottoRepository($this->ctx->db,$this->aziendaId());}
 public function index(): Response{$prodotti=$this->repo()->records();return $this->render('magazzino/index',compact('prodotti'));}
 public function create(): Response{return $this->form(['codice'=>'','nome'=>'','categoria'=>'prodotto','produttore'=>'','fornitore'=>'','descrizione'=>'','unita_misura'=>'pz','giacenza'=>'0','scorta_minima'=>'0','costo_acquisto'=>'','prezzo_vendita'=>'','tracciamento_lotto'=>'0','note'=>''],null);}
 public function store(): Response{return $this->save(null);}
 public function edit(int $id): Response{$p=$this->repo()->find($id)??$this->notFound();return $this->form($p,$id);}
 public function update(int $id): Response{$this->repo()->find($id)??$this->notFound();return $this->save($id);}
 public function show(int $id): Response{$prodotto=$this->repo()->find($id)??$this->notFound();$movimenti=$this->repo()->movements($id);$lotti=$this->repo()->lotti($id);return $this->render('magazzino/show',compact('prodotto','movimenti','lotti'));}
 public function movement(int $id): Response
 {
  $p=$this->repo()->find($id)??$this->notFound();$d=$this->ctx->request->only(['tipo','quantita','causale','lotto','scadenza']);$errors=[];
  if(!in_array($d['tipo'],['carico','scarico','rettifica'],true))$errors[]='Seleziona una causale valida.';if(!is_numeric($d['quantita'])||(float)$d['quantita']<0||($d['tipo']!=='rettifica'&&(float)$d['quantita']<=0))$errors[]='La quantità deve essere maggiore di zero.';if($d['causale']==='')$errors[]='Scrivi una causale.';if($p['tracciamento_lotto']&&$d['lotto']==='')$errors[]='Per questo prodotto il lotto è obbligatorio.';if($errors)return $this->redirect('/app/magazzino/'.$id,'error',implode(' ',$errors));
  try{$this->ctx->db->transaction(function()use($id,$d,$p){$current=$this->ctx->db->fetchOne('SELECT giacenza FROM prodotti WHERE id=:id AND azienda_id=:az FOR UPDATE',['id'=>$id,'az'=>$this->aziendaId()]);$old=(float)$current['giacenza'];$amount=(float)$d['quantita'];$delta=$d['tipo']==='carico'?$amount:($d['tipo']==='scarico'?-$amount:$amount-$old);if($old+$delta<0)throw new \DomainException('La quantità disponibile non è sufficiente.');$lotId=null;if($d['lotto']!==''){$lot=$this->ctx->db->fetchOne('SELECT * FROM lotti_magazzino WHERE azienda_id=:az AND prodotto_id=:p AND lotto=:l FOR UPDATE',['az'=>$this->aziendaId(),'p'=>$id,'l'=>$d['lotto']]);if(!$lot){if($delta<0)throw new \DomainException('Il lotto indicato non ha disponibilità registrata.');$lotId=$this->ctx->db->insert('lotti_magazzino',['azienda_id'=>$this->aziendaId(),'prodotto_id'=>$id,'lotto'=>$d['lotto'],'scadenza'=>$d['scadenza']?:null,'quantita'=>$delta]);}else{$lotId=(int)$lot['id'];if((float)$lot['quantita']+$delta<0)throw new \DomainException('La disponibilità del lotto è insufficiente.');$this->ctx->db->update('lotti_magazzino',['quantita'=>(float)$lot['quantita']+$delta,'scadenza'=>$d['scadenza']?:$lot['scadenza']],['id'=>$lotId,'azienda_id'=>$this->aziendaId()]);}}$this->ctx->db->update('prodotti',['giacenza'=>$old+$delta],['id'=>$id,'azienda_id'=>$this->aziendaId()]);$this->ctx->db->insert('movimenti_magazzino',['azienda_id'=>$this->aziendaId(),'prodotto_id'=>$id,'lotto_id'=>$lotId,'tipo'=>$d['tipo'],'quantita'=>$delta,'causale'=>$d['causale'],'utente_id'=>$this->ctx->auth->id()]);});}catch(\DomainException $ex){return $this->redirect('/app/magazzino/'.$id,'error',$ex->getMessage());}
  $this->ctx->audit->record('movimento_magazzino','prodotto',$id,['tipo'=>$d['tipo']]);return $this->redirect('/app/magazzino/'.$id,'ok','Giacenza aggiornata e movimento registrato.');
 }
 public function consume(int $interventoId): Response
 {
  $intervento=(new InterventoRepository($this->ctx->db,$this->aziendaId()))->find($interventoId)??$this->notFound();if($this->ctx->auth->soloAssegnati()&&!(new InterventoRepository($this->ctx->db,$this->aziendaId()))->isAssigned($interventoId,$this->ctx->auth->id()))$this->notFound();$d=$this->ctx->request->only(['prodotto_id','lotto_id','quantita_prevista','quantita_prelevata','quantita_utilizzata','quantita_restituita']);$p=ctype_digit($d['prodotto_id'])?$this->repo()->find((int)$d['prodotto_id']):null;if(!$p)return $this->redirect('/app/interventi/'.$interventoId,'error','Seleziona un prodotto valido.');foreach(['quantita_prevista','quantita_prelevata','quantita_utilizzata','quantita_restituita'] as $k)if(!is_numeric($d[$k])||(float)$d[$k]<0)return $this->redirect('/app/interventi/'.$interventoId,'error','Controlla le quantità inserite.');$picked=(float)$d['quantita_prelevata'];$used=(float)$d['quantita_utilizzata'];$returned=(float)$d['quantita_restituita'];if($used+$returned>$picked)return $this->redirect('/app/interventi/'.$interventoId,'error','Utilizzato e restituito non possono superare il prelevato.');$lotId=$d['lotto_id']!==''&&ctype_digit($d['lotto_id'])?(int)$d['lotto_id']:null;if($p['tracciamento_lotto']&&!$lotId)return $this->redirect('/app/interventi/'.$interventoId,'error','Scegli il lotto per questo prodotto.');
  try{$this->ctx->db->transaction(function()use($d,$p,$interventoId,$lotId,$picked,$returned){$old=$this->ctx->db->fetchOne('SELECT * FROM intervento_prodotti WHERE azienda_id=:az AND intervento_id=:i AND prodotto_id=:p AND ((lotto_id=:l1) OR (lotto_id IS NULL AND :l2 IS NULL)) LIMIT 1 FOR UPDATE',['az'=>$this->aziendaId(),'i'=>$interventoId,'p'=>$p['id'],'l1'=>$lotId,'l2'=>$lotId]);$oldNet=$old?(float)$old['quantita_prelevata']-(float)$old['quantita_restituita']:0;$newNet=$picked-$returned;$delta=$newNet-$oldNet;$stock=$this->ctx->db->fetchOne('SELECT giacenza FROM prodotti WHERE id=:p AND azienda_id=:az FOR UPDATE',['p'=>$p['id'],'az'=>$this->aziendaId()]);if((float)$stock['giacenza']-$delta<0)throw new \DomainException('Giacenza insufficiente per il prelievo.');if($lotId){$lot=$this->ctx->db->fetchOne('SELECT * FROM lotti_magazzino WHERE id=:l AND prodotto_id=:p AND azienda_id=:az FOR UPDATE',['l'=>$lotId,'p'=>$p['id'],'az'=>$this->aziendaId()]);if(!$lot||(float)$lot['quantita']-$delta<0)throw new \DomainException('Giacenza insufficiente per il lotto selezionato.');$this->ctx->db->update('lotti_magazzino',['quantita'=>(float)$lot['quantita']-$delta],['id'=>$lotId,'azienda_id'=>$this->aziendaId()]);}$this->ctx->db->update('prodotti',['giacenza'=>(float)$stock['giacenza']-$delta],['id'=>$p['id'],'azienda_id'=>$this->aziendaId()]);if($delta!=0)$this->ctx->db->insert('movimenti_magazzino',['azienda_id'=>$this->aziendaId(),'prodotto_id'=>$p['id'],'lotto_id'=>$lotId,'intervento_id'=>$interventoId,'tipo'=>$delta>0?'prelievo_intervento':'reso_intervento','quantita'=>-$delta,'causale'=>'Materiali intervento #'.$interventoId,'utente_id'=>$this->ctx->auth->id()]);$values=['quantita_prevista'=>(float)$d['quantita_prevista'],'quantita_prelevata'=>$picked,'quantita_utilizzata'=>(float)$d['quantita_utilizzata'],'quantita_restituita'=>$returned];if($old)$this->ctx->db->update('intervento_prodotti',$values,['id'=>(int)$old['id'],'azienda_id'=>$this->aziendaId()]);else $this->ctx->db->insert('intervento_prodotti',['azienda_id'=>$this->aziendaId(),'intervento_id'=>$interventoId,'prodotto_id'=>$p['id'],'lotto_id'=>$lotId]+$values);});}catch(\DomainException $ex){return $this->redirect('/app/interventi/'.$interventoId,'error',$ex->getMessage());}
  $this->ctx->audit->record('prodotti_intervento','intervento',$interventoId,['prodotto_id'=>$p['id']]);return $this->redirect('/app/interventi/'.$interventoId,'ok','Materiali aggiornati e giacenza registrata.');
 }
 private function save(?int $id): Response{$d=$this->ctx->request->only(['codice','nome','categoria','produttore','fornitore','descrizione','unita_misura','scorta_minima','costo_acquisto','prezzo_vendita','note']);$d['tracciamento_lotto']=$this->ctx->request->post('tracciamento_lotto')==='1'?1:0;$errors=[];if($d['nome']==='')$errors['nome']='Il nome è obbligatorio.';foreach(['scorta_minima','costo_acquisto','prezzo_vendita'] as $k)if($d[$k]!==''&&(!is_numeric($d[$k])||(float)$d[$k]<0))$errors[$k]='Inserisci un valore valido.';if($errors)return $this->form($d,$id,$errors,422);if($id)$this->repo()->update($id,$d);else{$d['giacenza']=0;$id=$this->repo()->create($d);} $this->ctx->audit->record($id?'salvataggio':'creazione','prodotto',$id);return $this->redirect('/app/magazzino/'.$id,'ok','Prodotto salvato.');}
 private function form(array $prodotto,?int $id,array $errors=[],int $status=200): Response{return $this->render('magazzino/form',compact('prodotto','id','errors'),'layout',$status);}
}
